                "document": "Document2",
                "authority": "Authority2",
                "disaster": "flood",
                "pages": [3, 4]
            },
            "text": "Content of Document2"
        }
    ]
    context = build_context(results)
    assert "Document1" in context
    assert "Authority1" in context
    assert "earthquake" in context
    assert "Document2" in context
    assert "Authority2" in context
    assert "flood" in context
    assert "Page(s): [1, 2]" in context
    assert "Page(s): [3, 4]" in context
    assert "Content of Document1" in context
